"use client";

import DashboardLayout from "@/components/layout/dashboard-layout";
import DataTable from "@/components/tables/data-table";
import { orderColumns } from "@/components/orders/order-columns";
import { getOrders } from "@/services/orders";
import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import { useState } from "react";

export default function OrdersPage() {
  const [type, setType] = useState<string | undefined>(undefined);

  const { data, isLoading } = useQuery({
    queryKey: ["orders", type],
    queryFn: () => getOrders({ type }),
  });

  return (
    <DashboardLayout>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Orders</h1>
        
        <div className="flex gap-4">
          <select 
            className="border rounded-lg px-3 py-2 text-sm"
            value={type || ""}
            onChange={(e) => setType(e.target.value || undefined)}
          >
            <option value="">All Types</option>
            <option value="SALE">Sales</option>
            <option value="PURCHASE">Purchases</option>
          </select>

          <Link
            href="/orders/create"
            className="bg-teal-600 text-white px-4 py-2 rounded-lg text-sm"
          >
            Create Order
          </Link>
        </div>
      </div>

      {isLoading ? (
        <p>Loading...</p>
      ) : (
        <DataTable columns={orderColumns} data={data || []} />
      )}
    </DashboardLayout>
  );
}
